var strip = root.querySelector('.sch-gallery-snap-strip');
var slides = [].slice.call(root.querySelectorAll('.sch-gallery-snap-slide'));
var dots = [].slice.call(root.querySelectorAll('.sch-gallery-snap-dot'));
var titleEl = root.querySelector('.sch-gallery-snap-t');
var subEl = root.querySelector('.sch-gallery-snap-s');
var nowEl = root.querySelector('.sch-gallery-snap-now');
var reduce = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
var active = -1, queued = false;

function nearest(){
  var sr = strip.getBoundingClientRect();
  var best = 0, bv = -1;
  for (var i = 0; i < slides.length; i++) {
    var r = slides[i].getBoundingClientRect();
    var vis = Math.min(r.right, sr.right) - Math.max(r.left, sr.left);
    if (vis > bv + 0.5) { bv = vis; best = i; }
  }
  return best;
}

function sync(){
  var i = nearest();
  if (i === active) return;
  active = i;
  for (var k = 0; k < slides.length; k++) {
    slides[k].classList.toggle('is-on', k === i);
    dots[k].classList.toggle('is-on', k === i);
    dots[k].setAttribute('aria-current', k === i ? 'true' : 'false');
  }
  titleEl.textContent = slides[i].getAttribute('data-t');
  subEl.textContent = slides[i].getAttribute('data-s');
  nowEl.textContent = String(i + 1);
}

function goTo(i){
  i = Math.max(0, Math.min(slides.length - 1, i));
  var delta = slides[i].getBoundingClientRect().left - (strip.getBoundingClientRect().left + 14);
  strip.scrollTo({ left: strip.scrollLeft + delta, behavior: reduce ? 'auto' : 'smooth' });
}

strip.addEventListener('scroll', function(){
  if (queued) return;
  queued = true;
  requestAnimationFrame(function(){
    if (!root.isConnected) return;
    queued = false;
    sync();
  });
});

strip.addEventListener('keydown', function(e){
  if (e.key === 'ArrowRight') { goTo(active + 1); e.preventDefault(); }
  else if (e.key === 'ArrowLeft') { goTo(active - 1); e.preventDefault(); }
  else if (e.key === 'Home') { goTo(0); e.preventDefault(); }
  else if (e.key === 'End') { goTo(slides.length - 1); e.preventDefault(); }
});

dots.forEach(function(d, i){ d.addEventListener('click', function(){ goTo(i); }); });
sync();

