speeds.forEach(function(b){
  b.addEventListener('click', function(){
    speed = parseFloat(b.getAttribute('data-v'));
    speeds.forEach(function(x){
      var on = x === b;
      x.classList.toggle('is-on', on);
      x.setAttribute('aria-pressed', on ? 'true' : 'false');
