function bar(){
  var w = track.scrollWidth || 1;
  var frac = Math.min(1, track.clientWidth / w);
  var max = track.scrollWidth - track.clientWidth;
  thumb.style.width = (frac * 100).toFixed(2) + '%';
  thumb.style.left = (max > 0 ? (track.scrollLeft / max) * (100 - frac * 100) : 0).toFixed(2) + '%';
