  if (!down) return;
  var dx = e.clientX - startX;
  if (Math.abs(dx) > 4) moved = true;
  track.scrollLeft = startL - dx;
  var dt = e.timeStamp - lastT;
  if (dt > 0) v = (e.clientX - lastX) / dt * 16;
  lastX = e.clientX; lastT = e.timeStamp;
  e.preventDefault();
});

