  cancelAnimationFrame(raf);
  raf = requestAnimationFrame(function step(){
    if (!root.isConnected) return;
    track.scrollLeft -= v;
    v *= 0.94;
    if (Math.abs(v) > 0.4) raf = requestAnimationFrame(step);
  });
