var items = [].slice.call(root.querySelectorAll('.sch-timeline-rail-item'));
var yearEl = root.querySelector('.sch-timeline-rail-year');
var queued = false, active = -1;

function update(){
  var max = track.scrollWidth - track.clientWidth;
  var p = max > 0 ? track.scrollLeft / max : 0;
  root.style.setProperty('--sch-timeline-rail-p', p.toFixed(4));
  var line = track.getBoundingClientRect().left + 24 + p * Math.max(0, track.clientWidth - 48);
  var best = 0, bd = Infinity;
  for (var i = 0; i < items.length; i++) {
    var d = Math.abs(items[i].getBoundingClientRect().left + 6 - line);
    if (d < bd) { bd = d; best = i; }
  }
  if (best === active) return;
  active = best;
  for (var k = 0; k < items.length; k++) {
    items[k].classList.toggle('is-on', k === best);
    items[k].classList.toggle('is-past', k < best);
  }
  yearEl.textContent = items[best].getAttribute('data-year');
}

track.addEventListener('scroll', function(){
  if (queued) return;
  queued = true;
  requestAnimationFrame(function(){
    if (!root.isConnected) return;
    queued = false;
    update();
  });
});
