var strip = root.querySelector('.sch-step-flow-strip');
var steps = [].slice.call(root.querySelectorAll('.sch-step-flow-step'));
var fill = root.querySelector('.sch-step-flow-fill');
var head = root.querySelector('.sch-step-flow-h');
var desc = root.querySelector('.sch-step-flow-d');
var nowEl = root.querySelector('.sch-step-flow-now');
var actions = [].slice.call(root.querySelectorAll('.sch-step-flow-btn'));
var reduce = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
var i = 2;

function render(){
  steps.forEach(function(s, k){
    s.classList.toggle('is-done', k < i);
    s.classList.toggle('is-on', k === i);
    s.disabled = k > i;
    if (k === i) s.setAttribute('aria-current', 'step');
    else s.removeAttribute('aria-current');
  });
  fill.style.width = (i / (steps.length - 1) * 100).toFixed(2) + '%';
  head.textContent = steps[i].querySelector('.sch-step-flow-name').textContent;
  desc.textContent = steps[i].getAttribute('data-d');
  nowEl.textContent = String(i + 1);
  actions[0].disabled = i === 0;
  actions[1].disabled = i === steps.length - 1;
  actions[1].textContent = i === steps.length - 2 ? 'Place order' : 'Continue';
  var el = steps[i];
  var sr = strip.getBoundingClientRect(), er = el.getBoundingClientRect();
  var target = strip.scrollLeft + (er.left - sr.left) - (strip.clientWidth - er.width) / 2;
  strip.scrollTo({ left: Math.max(0, target), behavior: reduce ? 'auto' : 'smooth' });
}

actions.forEach(function(b){
  b.addEventListener('click', function(){
    i = Math.max(0, Math.min(steps.length - 1, i + parseInt(b.getAttribute('data-go'), 10)));
    render();
  });
});

steps.forEach(function(s, k){
  s.addEventListener('click', function(){
    if (k > i) return;
    i = k;
    render();
  });
});

render();
